import React from "react";
import { Link } from "react-router-dom";
import { Swiper, SwiperSlide } from "swiper/react";
import { Navigation } from "swiper/modules";
import "swiper/css";
import "swiper/css/navigation";

// 🚨 [수정 1] .json 확장자를 붙여서 확실히 불러옵니다!
import bestData from "../data.json"; 

function BestSellers() {
  return (
    <div className="best-sellers-container">
      <h2 className="best-title">B E S T</h2>

      <Swiper
        modules={[Navigation]}
        spaceBetween={20}
        slidesPerView={4}
        navigation={true}
        slidesPerGroup={4}
        loop={false}
        className="mySwiper"
      >
        {bestData.map((item) => (
          <SwiperSlide key={item.id}>
            <Link to={`/detail/${item.id}`} className="product-link-wrapper">
              <div className="product-card">
                <div className="product-img-wrapper">
                  {/* 🚨 [수정 2] 이미지 경로 앞에 process.env.PUBLIC_URL 을 꼭 붙여야 엑박이 안 뜹니다! */}
                  <img 
                    src={process.env.PUBLIC_URL + item.img} 
                    alt={item.title} 
                    className="p-img" 
                  />
                  <div className="best-number-badge">
                    BEST
                    <br />
                    {item.id}
                  </div>
                  <div className="cart-btn-round">🛒</div>
                </div>
                <div className="product-info">
                  <p className="p-name">{item.title}</p>
                  <p className="p-price-row">
                    <span className="current-price">{item.price}원</span>
                    {item.oldPrice && (
                      <span className="old-price">{item.oldPrice}원</span>
                    )}
                  </p>
                  <div className="p-tag-row">
                    {item.tags &&
                      item.tags.map((tag) => (
                        <span key={tag} className="red-tag">
                          {tag}
                        </span>
                      ))}
                  </div>
                </div>
              </div>
            </Link>
          </SwiperSlide>
        ))}
      </Swiper>
    </div>
  );
}

export default BestSellers;