import React from "react";
import { Swiper, SwiperSlide } from "swiper/react";
import { Navigation, Pagination, Autoplay } from "swiper/modules";

import "swiper/css";
import "swiper/css/navigation";
import "swiper/css/pagination";

function PromoSection() {
  return (
    <div className="promo-container">
      {/* 1. 왼쪽 3단 슬라이더 영역 */}
      <div className="promo-left">
        <Swiper
          modules={[Navigation, Pagination, Autoplay]}
          navigation={true}
          pagination={{ clickable: true }}
          autoplay={{ delay: 3500 }}
          loop={true}
          autoHeight={true} 
          className="promo-swiper"
        >
          {/* 🚨 [핵심 수정] 모든 이미지 src 앞에 process.env.PUBLIC_URL 를 붙입니다! */}
          <SwiperSlide>
            <img src={process.env.PUBLIC_URL + "/img/left1.jpg"} alt="프로모션 1" />
          </SwiperSlide>
          <SwiperSlide>
            <img src={process.env.PUBLIC_URL + "/img/left2.jpg"} alt="프로모션 2" />
          </SwiperSlide>
          <SwiperSlide>
            <img src={process.env.PUBLIC_URL + "/img/left3.jpg"} alt="프로모션 3" />
          </SwiperSlide>
        </Swiper>
      </div>

      {/* 2. 오른쪽 고정 이미지 영역 */}
      <div className="promo-right">
        <div className="promo-rt">
          {/* 🚨 여기도 잊지 말고 PUBLIC_URL 추가! */}
          <img src={process.env.PUBLIC_URL + "/img/promo_rt.jpg"} alt="오른쪽 위" />
        </div>
        <div className="promo-rb">
          {/* 🚨 여기도 잊지 말고 PUBLIC_URL 추가! */}
          <img src={process.env.PUBLIC_URL + "/img/promo_rb.jpg"} alt="오른쪽 아래" />
        </div>
      </div>
    </div>
  );
}

export default PromoSection;